    static boolean jsonFieldsBody(StringBuilder b, TableVariable.NodeGraph graph, Value v, int depth, boolean first) {
        if (!first) { b.append(','); }
        first = false;
        TableJson.indent(b, depth);
        TableJson.esc(b, "f0");
        b.append(": ");
        b.append(Integer.toString(v.f0));
        if (!first) { b.append(','); }
        first = false;
        TableJson.indent(b, depth);
        TableJson.esc(b, "f1");
        b.append(": ");
        b.append(Integer.toString(v.f1));
        if (!first) { b.append(','); }
        first = false;
        TableJson.indent(b, depth);
        TableJson.esc(b, "f2");
        b.append(": ");
        b.append(Integer.toString(v.f2));
        if (!first) { b.append(','); }
        first = false;
        TableJson.indent(b, depth);
        TableJson.esc(b, "f3");
        b.append(": ");
        b.append(Integer.toString(v.f3));
        if (!first) { b.append(','); }
        first = false;
        TableJson.indent(b, depth);
        TableJson.esc(b, "f4");
        b.append(": ");
        b.append(Integer.toString(v.f4));
        if (!first) { b.append(','); }
        first = false;
        TableJson.indent(b, depth);
        TableJson.esc(b, "f5");
        b.append(": ");
        b.append(Integer.toString(v.f5));
        if (!first) { b.append(','); }
        first = false;
        TableJson.indent(b, depth);
        TableJson.esc(b, "f6");
        b.append(": ");
        b.append(Integer.toString(v.f6));
        if (!first) { b.append(','); }
        first = false;
        TableJson.indent(b, depth);
        TableJson.esc(b, "f7");
        b.append(": ");
        b.append(Integer.toString(v.f7));
        if (!first) { b.append(','); }
        first = false;
        TableJson.indent(b, depth);
        TableJson.esc(b, "f8");
        b.append(": ");
        b.append(Integer.toString(v.f8));
        if (!first) { b.append(','); }
        first = false;
        TableJson.indent(b, depth);
        TableJson.esc(b, "f9");
        b.append(": ");
        b.append(Integer.toString(v.f9));
        return first;
    }

    public static void writeJsonPointer(StringBuilder b, TableVariable.NodeGraph graph, Value child, int depth) {
        if (child == null) { b.append("null"); return; }
        if (graph.useCount(child) <= 1) {
            jsonFields(b, graph, child, depth);
            return;
        }
        Long label = graph.labels.get(child);
        if (label == null) {
            label = (long) (graph.labels.size() + 1);
            graph.labels.put(child, label);
            b.append('{' );
            TableJson.indent(b, depth + 1);
            b.append("\"&node\": ").append(label);
            jsonFieldsBody(b, graph, child, depth + 1, false);
            TableJson.indent(b, depth);
            b.append('}');
        } else {
            b.append('{' );
            TableJson.indent(b, depth + 1);
            b.append("\"&node\": ").append(label);
            TableJson.indent(b, depth);
            b.append('}');
        }
    }

    public static Value readJsonPointer(TableJson.In in, long targetTypeId) {
        if (in.peek() == 'n') { in.lit("null"); return null; }
        if (in.peek() != '{' ) { in.skipValue(); in.rep.kindMismatch++; return null; }
        int start = in.p;
        in.p++;
        in.space();
        if (in.peek() == '}') { in.p = start; Value v = new Value(); jsonReadFields(in, v); return v; }
        String key = in.scanString();
        if (in.bad || key == null) return null;
        if (!"&node".equals(key)) { in.p = start; Value v = new Value(); jsonReadFields(in, v); return v; }
        if (in.peek() != ':') { in.bad = true; return null; }
        in.p++;
        long labelId = in.scanLabel();
        if (in.bad || labelId <= 0) return null;
        int c = in.peek();
        if (c == '}') {
            in.p++;
            TableJson.LabelEntry entry = in.labels.get(labelId);
            if (entry == null || entry.open) { in.bad = true; return null; }
            if (entry.typeId == 0) { return null; }
            if (entry.typeId != targetTypeId) { in.rep.kindMismatch++; return null; }
            return (Value) entry.value;
        } else if (c == ',') {
            in.p++;
            if (in.peek() == '}') { in.bad = true; return null; }
            if (in.labels.containsKey(labelId)) { in.bad = true; return null; }
            Value child = new Value();
            TableJson.LabelEntry entry = new TableJson.LabelEntry(child, targetTypeId, true);
            in.labels.put(labelId, entry);
            jsonReadFieldsBody(in, child);
            entry.open = false;
            return child;
        } else {
            in.bad = true; return null;
        }
    }

    static void jsonReadFields(TableJson.In in, Value v) {
        in.space();
        if (in.peek() != '{' ) { in.bad = true; return; }
        in.p++;
        jsonReadFieldsBody(in, v);
    }

    static void jsonReadFieldsBody(TableJson.In in, Value v) {
        while (true) {
            int c = in.peek();
            if (c == 0) { in.bad = true; return; }
            if (c == '}') { in.p++; return; }
            String key = in.scanString();
            if (in.bad) { return; }
            if (key != null && key.startsWith("&")) { in.bad = true; return; }
            if (in.peek() != ':') { in.bad = true; return; }
            in.p++;
            if ("f0".equals(key)) {
                if (in.peek() == '-' || (in.peek() >= '0' && in.peek() <= '9')) { v.f0 = (int) in.integer(true, -100, 100); }
                else { in.skipValue(); in.rep.kindMismatch++; }
            } else             if ("f1".equals(key)) {
                if (in.peek() == '-' || (in.peek() >= '0' && in.peek() <= '9')) { v.f1 = (int) in.integer(true, 0, 65535); }
                else { in.skipValue(); in.rep.kindMismatch++; }
            } else             if ("f2".equals(key)) {
                if (in.peek() == '-' || (in.peek() >= '0' && in.peek() <= '9')) { v.f2 = (int) in.integer(true, -1000000, 1000000); }
                else { in.skipValue(); in.rep.kindMismatch++; }
            } else             if ("f3".equals(key)) {
                if (in.peek() == '-' || (in.peek() >= '0' && in.peek() <= '9')) { v.f3 = (int) in.integer(true, 0, 3); }
                else { in.skipValue(); in.rep.kindMismatch++; }
            } else             if ("f4".equals(key)) {
                if (in.peek() == '-' || (in.peek() >= '0' && in.peek() <= '9')) { v.f4 = (int) in.integer(true, -15, 15); }
                else { in.skipValue(); in.rep.kindMismatch++; }
            } else             if ("f5".equals(key)) {
                if (in.peek() == '-' || (in.peek() >= '0' && in.peek() <= '9')) { v.f5 = (int) in.integer(true, 0, 1000); }
                else { in.skipValue(); in.rep.kindMismatch++; }
            } else             if ("f6".equals(key)) {
                if (in.peek() == '-' || (in.peek() >= '0' && in.peek() <= '9')) { v.f6 = (int) in.integer(true, -2048, 2047); }
                else { in.skipValue(); in.rep.kindMismatch++; }
            } else             if ("f7".equals(key)) {
                if (in.peek() == '-' || (in.peek() >= '0' && in.peek() <= '9')) { v.f7 = (int) in.integer(true, 0, 255); }
                else { in.skipValue(); in.rep.kindMismatch++; }
            } else             if ("f8".equals(key)) {
                if (in.peek() == '-' || (in.peek() >= '0' && in.peek() <= '9')) { v.f8 = (int) in.integer(true, -600000, 600000); }
                else { in.skipValue(); in.rep.kindMismatch++; }
            } else             if ("f9".equals(key)) {
                if (in.peek() == '-' || (in.peek() >= '0' && in.peek() <= '9')) { v.f9 = (int) in.integer(true, 0, 100); }
                else { in.skipValue(); in.rep.kindMismatch++; }
            } else {
                in.skipValue(); in.rep.unknown++;
            }
            c = in.peek();
            if (c == ',') { in.p++; continue; }
            if (c == '}') { in.p++; return; }
            in.bad = true; return;
        }
    }

